const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={name:'Explorer',xp:0,done:[],rewards:[],weak:[],level:'Explorer',motion:false};let storageOK=true;try{const saved=JSON.parse(localStorage.getItem('bodyquest-v1'));if(saved&&Array.isArray(saved.done)&&Array.isArray(saved.rewards))state={...state,...saved}}catch{storageOK=false}
function save(){try{localStorage.setItem('bodyquest-v1',JSON.stringify(state))}catch{storageOK=false}}
/* The six System Keys: one source of truth for the home chip, the expedition summary and the dashboard. */
function keysEarned(){const s=k=>(state[k]&&typeof state[k]==='object')?state[k]:{};return (state.done.includes(8)?1:0)+(s('integumentary').mastery?1:0)+(s('respiratory').mastery?1:0)+(s('excretory').mastery?1:0)+(s('circ').mastery?1:0)+((s('muscle').done||[]).includes(8)?1:0)}
function reward(id,xp){if(state.rewards.includes(id))return;state.rewards.push(id);state.xp+=xp;save();toast('+'+xp+' XP · Discovery unlocked');animateXP(state.xp-xp,state.xp)}
function toast(text){$('.toast')?.remove();let n=document.createElement('div');n.className='toast';n.role='status';n.textContent=text;document.body.append(n);setTimeout(()=>n.remove(),3000)}
const icon=(name)=>{let d={world:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',detective:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',connect:'<circle cx="5" cy="12" r="3"/><circle cx="19" cy="5" r="3"/><circle cx="19" cy="19" r="3"/><path d="m8 11 8-5M8 13l8 5"/>',badge:'<path d="m8 14-2 8 6-3 6 3-2-8"/><circle cx="12" cy="8" r="6"/>',book:'<path d="M12 5v16M12 5Q7 1 2 4v15q5-3 10 2 5-5 10-2V4q-5-3-10 1"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true">${d[name]||d.world}</svg>`};
const missions=[['Meet your skeleton','Discover the two divisions of your framework.'],['Bone detective','Match a bone’s shape to the job it does.'],['Inside a bone','Find out how bones stay strong but light.'],['Joint lab','Explore the ways your body can move.'],['Bone remodeling','Balance demolition and construction.'],['Repair the fracture','Rebuild a bone, one stage at a time.'],['Body Detective','Follow the evidence. Solve four mysteries.']];
const systems=[['BODY SHIELD','Integumentary System','THE BODY SHIELD','#ae8c6b','◈'],['FRAMEWORK','Skeletal System','THE FRAMEWORK','#098b84','⌘'],['POWER','Muscular System','THE POWER SYSTEM','#c67773','ϟ'],['OXYGEN','Respiratory System','THE OXYGEN MISSION','#5694b0','♧'],['TRANSPORT','Circulatory System','THE TRANSPORT NETWORK','#bb6470','♡'],['FILTER','Excretory System','THE FILTER SYSTEM','#9b86b1','◇']];
const pct=()=>Math.round(state.done.filter(x=>x<=8).length/8*100),status=p=>p===0?'Not Started':p<40?'Exploring':p<70?'Developing':p<90?'Strong':'Mastered';
function nextMission(){return Math.min(8,Array.from({length:8},(_,i)=>i+1).find(i=>!state.done.includes(i))||8)}
function skeleton(mode='all',interactive=false){let axial=mode==='appendicular'?'#c9d8db':'#70b9ac',app=mode==='axial'?'#c9d8db':'#88bfb8';return `<svg viewBox="0 0 240 470" role="img" aria-label="Simplified anterior skeleton. Axial: skull, ribs, sternum and spine. Appendicular: girdles and limbs."><g fill="none" stroke="#dde9e7" stroke-width="1"><ellipse cx="120" cy="240" rx="101" ry="203"/><path d="M120 10v450M10 240h220"/></g><g data-part="axial" fill="${axial}" stroke="#478f86" stroke-width="1.2"><path d="M100 49Q94 18 120 17Q146 18 140 49l-8 11h-24Z"/><path d="M108 59v9q12 8 24 0v-9"/><path fill="#f0f7f6" d="M103 39l10-2 1 8-9 2ZM127 37l10 2-2 8-9-2ZM117 49l3-7 4 7Z"/><path d="M116 74h8v129h-8z"/>${Array.from({length:15},(_,i)=>`<rect x="113" y="${77+i*9}" width="14" height="6" rx="2"/>`).join('')}<rect x="116" y="92" width="8" height="58" rx="3"/>${Array.from({length:7},(_,i)=>`<path d="M116 ${95+i*9}Q${74-i} ${86+i*10} ${82-i} ${108+i*9}Q88 ${123+i*8} 116 ${105+i*9}M124 ${95+i*9}Q${166+i} ${86+i*10} ${158+i} ${108+i*9}Q152 ${123+i*8} 124 ${105+i*9}" fill="none" stroke="${axial}" stroke-width="5"/>`).join('')}<path d="m111 211 9 20 9-20z"/></g><g data-part="appendicular" fill="${app}" stroke="#478f86" stroke-width="1.2"><path d="M76 87q17-12 39-3l-1 6q-22-6-38 3ZM125 84q22-9 39 3v6q-16-9-38-3Z"/><path d="M77 94l-10 20 16 16 4-33M163 94l10 20-16 16-4-33"/><path d="M68 105q-7-4-10 4l-10 69q4 9 10 0l13-67ZM172 105q7-4 10 4l10 69q-4 9-10 0l-13-67Z"/><path d="m48 186-9 67 5 2 11-69Zm10 0-6 69 5 1 8-68ZM192 186l9 67-5 2-11-69Zm-10 0 6 69-5 1-8-68Z"/><path d="m40 257-7 17 18 4 7-18ZM200 257l7 17-18 4-7-18Z"/>${[0,1,2,3,4].map(i=>`<path d="m${34+i*5} 278-${4-i} ${20-Math.abs(i-2)*3}m${172+i*5+17} -${20-Math.abs(i-2)*3} ${4-i} ${20-Math.abs(i-2)*3}" fill="none" stroke="${app}" stroke-width="3"/>`).join('')}<path d="M107 205q-17-17-24 2-6 18 10 30l17-11 10 8 10-8 17 11q16-12 10-30-7-19-24-2l-3 19h-20Z"/><path fill="#f0f7f6" d="M94 216q-9 0-3 12l10-3ZM146 216q9 0 3 12l-10-3Z"/><path d="M95 235q-9-4-10 6l13 81q-4 12 5 13 12-1 7-12l-10-79ZM145 235q9-4 10 6l-13 81q4 12-5 13-12-1-7-12l10-79Z"/><ellipse cx="104" cy="339" rx="7" ry="8"/><ellipse cx="136" cy="339" rx="7" ry="8"/><path d="m98 351 2 78 7 0 1-78Zm-6 0 2 76 3 0-1-76ZM142 351l-2 78h-7l-1-78Zm6 0-2 76h-3l1-76Z"/><path d="m100 433-14 15q-3 8 9 6l13-5-1-16ZM140 433l14 15q3 8-9 6l-13-5 1-16Z"/></g>${interactive?'<g fill="#0a7577" font-family="sans-serif" font-size="11"><text x="155" y="35">Skull</text><text x="152" y="150">Ribs</text><text x="155" y="298">Femur</text></g>':''}</svg>`}
function layout(content,active='world'){document.body.classList.toggle('motionoff',state.motion);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#home" aria-label="InnerU"><span class="brandmark"><img src="inneru-mark.svg?v=2" alt="" width="52" height="52"></span><span class="brandname">Inner<span>U</span></span></a><div class="school">Um Al-Emarat School</div><div class="navlabel">Your expedition</div><nav>${[['home','world','Explore Worlds'],['dashboard','dashboard','My Dashboard'],['detective','detective','Body Detective'],['connect','connect','System Connections'],['badges','badge','My Achievements']].map(([r,i,t])=>`<a class="navlink ${active===i?'active':''}" href="#${r}">${icon(i)}${t}</a>`).join('')}</nav><div class="sidebottom"><div class="row"><div class="schoolseal"><img src="inneru-mark.svg?v=2" alt="" width="34" height="34"></div><div><b class="micro">InnerU</b><p class="micro sidebar-mantra">Explore What’s Inside.</p></div></div><a class="navlink" href="#sources">${icon('book')}Science references</a></div></aside><div><header class="topbar"><span class="crumb">Grade 10 Science <span aria-hidden="true"> / </span> ${active==='world'?'Explore Worlds':active==='dashboard'?'My Dashboard':'Your expedition'}</span><div class="profile"><span class="xp">✧ ${state.xp} XP</span><span class="avatar">${esc(state.name.slice(0,1).toUpperCase())}</span><span class="name micro">${esc(state.name)}</span></div></header><main class="main" id="main" tabindex="-1">${content}<footer><span class="footer-brand"><img src="inneru-mark.svg?v=2" alt="" width="22" height="22"> © ${new Date().getFullYear()} InnerU · Um Al-Emarat School</span><nav><a href="#about">About</a><a href="#privacy">Privacy</a><a href="#sources">Sources</a><a href="#attribution">Attribution</a></nav></footer></main></div></div>`}
const systemTeasers=['Protect the body from the outside world.','Build. Protect. Move.','Discover how muscles create movement.','Follow oxygen from the lungs to the blood.',"Travel through the body’s delivery network.",'Discover how the body cleans and balances its blood.'];
const systemDetails=['Your first line of defense, sensation and temperature control.','206 bones working together for support, protection and movement.','Muscles pull on bones to turn energy into movement.','Lungs exchange gases: oxygen enters the blood and carbon dioxide leaves.','The heart and blood vessels connect cells with oxygen and nutrients.','Kidneys filter blood; ureters carry urine to the bladder.'];
const systemIcon=i=>i===2?`<svg viewBox="0 0 32 32" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Flexed arm muscle"><path d="M3 20q5-3 9-2l7 2 4-2q0-6-3-10L17 5q-2-4 1-4 6-1 9 6l3 12q1 7-6 8l-7-3q-7 2-14-1" fill="none" stroke="#b4636c" stroke-width="1.5" stroke-linejoin="round"/><path d="M4 20q9-6 18 2-8 4-18 0Z" fill="#d78787" stroke="#b4636c" stroke-width=".7"/><path d="M8 24q8 1 14-2-3 5-10 4Z" fill="#9bbfa2" stroke="#79a888" stroke-width=".5"/></svg>`:`<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${['<path d="M5 12q5-5 11 0t11 0M5 18q5-5 11 0t11 0M5 24q5-5 11 0t11 0M16 5v6"/>','<path d="M10 8q-1-6-6-3-4 5 2 8l13 13q3 6 8 2 3-5-3-6L11 9Z"/>','<path d="M3 21q4-4 8-3l6 1 4-2 2-9-2-2-1-3 3-1 3 3-1 5-2 11q-3 5-8 3l-9 1Z"/><path d="M6 19q5-5 10-3l5 4M11 23l7-1"/>','<path d="M14 8v8l-6 6M18 8v8l6 6M12 13Q7 8 4 23q0 6 9 3ZM20 13q5-5 8 10 0 6-9 3Z"/>','<path d="M16 27C-4 15 7 5 15 13 22 2 36 14 16 27ZM16 12V5h5v6"/>','<path d="M10 6q-8-3-7 9 2 7 7 3l-1-5 2-3ZM22 6q8-3 7 9-2 7-7 3l1-5-2-3ZM10 18l3 7m9-7-3 7M12 25q4-3 8 0l-1 4h-6Z"/>'][i]}</svg>`;
let selectedSystem=null,hoveredSystem=null;
function portal(i){const s=systems[i],p=i===1?pct():i===4?Math.round(circProgress().done.length/7*100):0;return `<article class="portal world-portal ${(i===1||i===4)?'playable':''}" data-card="${i}" style="--system-color:${s[3]}"><button class="system-select" data-system="${i}" aria-pressed="false" aria-label="Select ${s[1]}"><span class="world-card-top"><span class="system-icon">${systemIcon(i)}</span><span class="world-index">WORLD 0${i+1}</span></span><span class="world-card-name">${s[0]}</span><span class="scientific-name">${s[1]}</span>${(i===1||i===4)?`<span class="ready-label">${p===0?'Ready to explore':status(p)}</span><span class="progress-meta"><span>${p}% complete</span><span>${i===4?'Seven missions':'585 XP available'}</span></span><span class="bar"><i style="width:${p}%"></i></span>`:`<span class="world-teaser">${systemTeasers[i]}</span><span class="coming-label">${lockIcon()} Coming next</span>`}</button>${(i===1||i===4)?`<a class="btn enter-world" href="#${i===4?'circulatory':'world'}">Enter World <span aria-hidden="true">→</span></a>`:''}</article>`}
function lockIcon(){return '<svg viewBox="0 0 20 20" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><rect x="5" y="9" width="10" height="8" rx="2"/><path d="M7 9V6a3 3 0 0 1 6 0v3"/></svg>'}
function home(){selectedSystem=null;hoveredSystem=null;layout(`<section class="explore-screen"><section class="inneru-welcome" aria-labelledby="welcome-title"><div class="welcome-copy"><div class="welcome-kicker">InnerU <span aria-hidden="true" class="welcome-kicker-line"></span> THE HUMAN BODY, DISCOVERED</div><h1 id="welcome-title">Explore What’s <em>Inside.</em></h1><p class="welcome-slogan">Discover What Keeps You Alive.</p><p class="welcome-instruction">Choose a body system and begin your expedition.</p><button class="welcome-cta" type="button" id="explore-systems">Explore the Systems <span aria-hidden="true">↗</span></button></div><div class="welcome-art" aria-hidden="true"><div class="welcome-art-light"></div><img src="inneru-mark-light.svg?v=2" alt="" width="512" height="512"></div></section><section class="atlas anatomy-lab" aria-label="Interactive body system selector"><div class="scan-bar"><span><span class="scan-indicator"></span> HUMAN SYSTEMS MAP</span><span>ANTERIOR VIEW</span></div><div class="portals left-portals">${[0,1,2].map(portal).join('')}</div><div class="atlascenter explorer-body"><div class="anatomy-stage">${anatomyMap()}<div id="anatomy-tooltip" class="anatomy-tooltip" role="status" hidden></div></div><div class="body-instruction">Click the body or choose a system</div><div class="selected-system-panel" id="selected-system-panel" aria-live="polite"><div class="eyebrow">HUMAN SYSTEMS MAP</div><h2>Select a system to explore</h2><p>Every system has a role. Discover how they connect.</p></div></div><div class="portals right-portals">${[3,4,5].map(portal).join('')}</div><div class="scan-footer"><span>Discover What Keeps You Alive.</span><span>SIMPLIFIED EDUCATIONAL ANATOMY</span></div></section><nav class="world-journey" aria-label="Connected world journey">${['BODY SHIELD','FRAMEWORK','POWER','OXYGEN','TRANSPORT','FILTER'].map((t,i)=>`<button data-journey="${i}" style="--system-color:${systems[i][3]}" aria-label="Select world ${i+1}: ${t} · ${systems[i][1]}"><span>${i+1}</span>${t} · ${systems[i][1]}${(i===1||i===4)?'<b class="journey-playable">PLAYABLE</b>':''}</button>`).join('')}</nav><div class="finalmission final-destination"><div class="row"><span class="destination-lock">${lockIcon()}</span><div><div class="eyebrow muted">FINAL MISSION</div><h3>Keep the body alive</h3><p>Six System Keys. One connected challenge.</p></div></div><span class="chip">Locked · ${keysEarned()}/6 keys</span></div><div class="expedition-summary"><div><div class="eyebrow">YOUR EXPEDITION</div><h3>${pct()}% of the Framework (Skeletal System) explored</h3><p>${state.xp} XP earned · ${keysEarned()}/6 System Keys</p></div><a class="btn" href="#mission/${nextMission()}">${state.done.length?'Continue mission':'Begin your expedition'} →</a><a class="textlink" href="#dashboard">My Dashboard</a></div><div class="sectiontitle"><h2>Follow your curiosity</h2></div><div class="grid three"><a class="panel feature" style="text-decoration:none" href="#world"><div class="featureicon">${systemIcon(1)}</div><div><h3>The Framework (Skeletal System)</h3><p>Seven missions. One strong start.</p></div></a><a class="panel feature" style="text-decoration:none" href="#detective"><div class="featureicon">${icon('detective')}</div><div><h3>Follow the evidence</h3><p>A medical mystery awaits.</p></div></a><a class="panel feature" style="text-decoration:none" href="#connect"><div class="featureicon">${icon('connect')}</div><div><h3>Running on a hot day</h3><p>Discover how systems work together.</p></div></a></div></section>`);
$$('[data-system]').forEach(b=>{const i=+b.dataset.system;b.onmouseenter=()=>previewSystem(i);b.onmouseleave=()=>clearPreview();b.onfocus=()=>previewSystem(i);b.onblur=()=>clearPreview();b.onclick=()=>selectSystem(i)});
$$('[data-anatomy]').forEach(g=>{const i=+g.dataset.anatomy;g.onmouseenter=()=>previewSystem(i);g.onmouseleave=()=>clearPreview();g.onfocus=()=>previewSystem(i);g.onblur=()=>clearPreview();g.onclick=()=>selectSystem(i);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectSystem(i)}if(e.key==='Escape')resetSystem()}});
$('#explore-systems').onclick=()=>$('.anatomy-lab').scrollIntoView({behavior:motionReduced()?'instant':'smooth',block:'start'});
$$('[data-journey]').forEach(b=>b.onclick=()=>{selectSystem(+b.dataset.journey);$('.anatomy-lab').scrollIntoView({behavior:motionReduced()?'instant':'smooth',block:'start'})});
$$('.enter-world[href="#world"]').forEach(a=>a.onclick=e=>enterWorld(e));$('.anatomy-lab').onkeydown=e=>{if(e.key==='Escape')resetSystem()};highlightSystem(null)}
function motionReduced(){return state.motion||window.matchMedia('(prefers-reduced-motion: reduce)').matches}
function previewSystem(i){hoveredSystem=i;highlightSystem(i)}
function clearPreview(){hoveredSystem=null;highlightSystem(selectedSystem)}
function selectSystem(i){selectedSystem=i;hoveredSystem=null;highlightSystem(i);const tip=$('#anatomy-tooltip');tip.hidden=false;tip.textContent=i===1?'Enter the Framework (Skeletal System)':i===4?'Enter The Transport Network':'World coming soon';tip.style.setProperty('--system-color',systems[i][3])}
function resetSystem(){selectedSystem=null;hoveredSystem=null;$('#anatomy-tooltip').hidden=true;highlightSystem(null)}
function enterWorld(e){e.preventDefault();selectedSystem=1;highlightSystem(1);if(motionReduced()){location.hash='world';return}$('.anatomy-lab')?.classList.add('entering-world');setTimeout(()=>{if(!location.hash||location.hash==='#home')location.hash='world'},220)}
function highlightSystem(i){const map=$('#human-map');if(!map)return;map.classList.toggle('system-isolated',i!==null);map.setAttribute('data-selected',i===null?'none':String(i));$$('[data-anatomy]').forEach(g=>{const on=+g.dataset.anatomy===i;g.classList.toggle('anatomy-active',on);g.setAttribute('aria-pressed',String(on))});$$('[data-card]').forEach(c=>c.classList.toggle('selected',+c.dataset.card===i));$$('[data-system]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.system===i)));$$('[data-journey]').forEach(b=>b.classList.toggle('selected',+b.dataset.journey===i));const panel=$('#selected-system-panel');if(i===null){panel.innerHTML='<div class="eyebrow">HUMAN SYSTEMS MAP</div><h2>Select a system to explore</h2><p>Every system has a role. Discover how they connect.</p>';panel.style.removeProperty('--system-color')}else{panel.style.setProperty('--system-color',systems[i][3]);panel.innerHTML=`<div class="eyebrow">${systems[i][2]}</div><h2>${systems[i][1]}</h2><p>${systemDetails[i]}</p>${i===1?'<a class="btn selected-enter" href="#world">Enter the Framework (Skeletal System) →</a>':i===4?'<a class="btn selected-enter" href="#circulatory">Enter The Transport Network →</a>':`<span class="selected-locked">${lockIcon()} World coming soon</span>`}${selectedSystem!==null?'<button class="clear-selection" aria-label="Show all body systems">Show all systems</button>':''}`;if(i===1)$('.selected-enter')?.addEventListener('click',enterWorld);$('.clear-selection')?.addEventListener('click',resetSystem)}if(hoveredSystem!==null)$('#anatomy-tooltip').hidden=true;else if(selectedSystem!==null){$('#anatomy-tooltip').hidden=false;$('#anatomy-tooltip').textContent=selectedSystem===1?'Enter the Framework (Skeletal System)':selectedSystem===4?'Enter The Transport Network':'World coming soon'}}

function world(){layout(`<div class="worldbanner"><div><div class="eyebrow" style="color:#7cd7c9">WORLD 02 · Skeletal System</div><h1 style="margin-top:12px">The Framework (Skeletal System)</h1><p>Build. Protect. Move.</p></div><span class="chip">${pct()}% complete</span></div>${bodyAtlasMarkup('skeletal')}<div class="headrow"><div><h2>Your mission map</h2><p>Complete each investigation and its three checks to unlock the next.</p></div><label class="micro">Challenge level<select class="input" id="level">${['Explorer','Challenger','Master'].map(x=>`<option ${state.level===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="grid missiongrid">${missions.map((m,i)=>{let locked=i>0&&!state.done.includes(i),done=state.done.includes(i+1);return `<article class="panel missioncard ${locked?'locked':''}"><div class="missionnum">MISSION 0${i+1} ${done?' · ✓ COMPLETED':''}</div><h3>${m[0]}</h3><p>${m[1]}</p>${locked?'<button class="btn line" disabled>Locked · Finish previous mission</button>':`<a class="btn ${done?'secondary':''}" href="#mission/${i+1}">${done?'Explore again':'Start mission'} →</a>`}</article>`}).join('')}</div><div class="finalmission"><div><div class="eyebrow">BOSS CHALLENGE</div><h3>The athlete case</h3><p>Earn the Skeletal Master badge, 50 XP and your Framework Key (Skeletal System).</p></div>${state.done.includes(7)?'<a class="btn" href="#mission/8">Accept challenge →</a>':'<button class="btn line" disabled>Finish all 7 missions</button>'}</div>`);$('#level').onchange=e=>{state.level=e.target.value;save();toast(state.level+' challenge selected')};window.mountBodyAtlas?.('skeletal')}
const q=(text,options,answer,why)=>({text,options,answer,why});
const checks={
1:[q('How many bones does a typical adult skeleton have?',['106','206','306'],1,'A typical adult has 206 bones; individual variation is possible.'),q('Which division contains the arms and legs?',['Axial','Appendicular','Both equally'],1,'The appendicular skeleton includes the limbs and the girdles that attach them.'),q('Why are skull and ribs grouped with the axial skeleton?',['They form the central axis and protect vital organs.','They are all long bones.','They move the fingers.'],0,'The axial skeleton supports the central body and protects the brain, spinal cord and chest organs.')],
2:[q('A vertebra is which bone type?',['Flat','Short','Irregular'],2,'A vertebra has a complex shape, so it is an irregular bone.'),q('Which shape is well suited to broad protection?',['Flat bone','Long bone only','Every shape is identical'],0,'Flat bones such as the sternum provide broad protective surfaces.'),q('Why would femur-shaped bones work poorly in the wrist?',['A wrist needs several small bones for flexible movement.','Long bones contain no marrow.','Short bones cannot support weight.'],0,'Many small carpal bones allow small gliding movements while supporting the wrist.')],
3:[q('What does yellow marrow mainly store?',['Blood cells','Fat','Air'],1,'Yellow marrow contains fat; red marrow produces blood cells.'),q('A blood-cell production problem involves which tissue?',['Cartilage','Red marrow','Periosteum only'],1,'Red marrow is the blood-cell-producing tissue.'),q('How does spongy bone reduce weight while supporting loads?',['A lattice of struts supports forces without being solid throughout.','It is hollow air with no structure.','It has no minerals.'],0,'Its trabecular lattice provides support with less material than a solid mass.')],
4:[q('Which joint is normally immovable?',['Shoulder','Skull suture','Elbow'],1,'Skull sutures are fibrous joints that allow little or no movement.'),q('Which joint mainly bends and straightens?',['Hinge','Ball-and-socket','Pivot'],0,'A hinge joint mainly permits flexion and extension in one plane.'),q('Why is the shoulder more mobile than the elbow?',['Its ball fits a socket, allowing movement in several planes.','It has no bones.','Its bones never touch cartilage.'],0,'A ball-and-socket joint allows rotation and movement around multiple axes.')],
5:[q('Which cells remove bone tissue?',['Osteoblasts','Osteoclasts','Red blood cells'],1,'Osteoclasts resorb bone; osteoblasts form new bone.'),q('Removal is 5 units and formation is 2. What happens?',['Mass increases','Mass stays equal','Mass decreases'],2,'Formation minus removal is 2 − 5 = −3 units.'),q('Why can long-term inactivity weaken bone?',['Reduced loading can shift remodeling toward bone loss.','Bones stop containing living cells.','All marrow turns to air.'],0,'Mechanical loading influences bone remodeling; reduced loading can favor loss.')],
6:[q('What happens first after a fracture?',['Hard callus','Hematoma','Remodeling'],1,'Damaged blood vessels form a clot, or fracture hematoma.'),q('What bridges the break before a hard bony callus?',['Soft callus','Yellow marrow alone','A new joint'],0,'A soft fibrocartilaginous callus provides an early bridge.'),q('Why does stabilization support fracture healing?',['It limits disruptive movement while repair tissue forms.','It replaces all repair cells.','It prevents any blood reaching the bone.'],0,'Stability helps repair tissue bridge the fracture without repeated disruption.')],
7:[q('Which structure connects bone to bone?',['Tendon','Ligament','Muscle fibre'],1,'Ligaments join bones at joints; tendons attach muscle to bone.'),q('Inflammation of a fluid-filled cushioning sac is called…',['Bursitis','Sprain','Fracture'],0,'A bursa is a fluid-filled sac; its inflammation is bursitis.'),q('Why does immune attack suggest rheumatoid arthritis?',['It is an autoimmune condition affecting joint tissue.','Every sore knee has the same cause.','Ligaments are blood vessels.'],0,'The immune-system clue distinguishes rheumatoid arthritis from osteoarthritis.')],
8:[q('Which ankle structure is most likely damaged in this learning case?',['Ligament joining ankle bones','Tendon attaching muscle to bone','Red marrow'],0,'The twisting mechanism points toward an overstretched ligament in this simplified case.'),q('What is the likely injury?',['Sprain','Bursitis','Osteoarthritis'],0,'A sprain is a ligament injury. A normal X-ray does not rule out every real injury.'),q('Which Skeletal System function is affected most directly?',['Joint stability and movement','Sweat production','Urine production'],0,'Damaged ligaments reduce joint stability and can make movement painful.')]
};
/* Mix per-question helpers: keep one question object/tuple but move the correct option, so the answer is not always first. */
function mixQ(q){if(!Array.isArray(q))return q;let oi=-1,ai=-1;for(let i=0;i<q.length;i++){if(oi<0&&Array.isArray(q[i])&&q[i].length>1)oi=i;if(typeof q[i]==='number')ai=i}if(oi<0||ai<0||q[ai]<0||q[ai]>=q[oi].length)return q;const src=q[oi],n=src.length,ord=Array.from({length:n},(_,i)=>i);for(let i=n-1;i>0;i--){const j=Math.floor(Math.random()*(i+1)),t=ord[i];ord[i]=ord[j];ord[j]=t}const out=q.slice();out[oi]=ord.map(i=>src[i]);out[ai]=ord.indexOf(q[ai]);return out}
function mixQO(q){if(!q||!Array.isArray(q.options)||typeof q.answer!=='number')return q;const src=q.options,n=src.length,ord=Array.from({length:n},(_,i)=>i);for(let i=n-1;i>0;i--){const j=Math.floor(Math.random()*(i+1)),t=ord[i];ord[i]=ord[j];ord[j]=t}return{text:q.text,options:ord.map(i=>src[i]),answer:ord.indexOf(q.answer),why:q.why}}
for(const k in checks)checks[k]=checks[k].map(mixQO);
let activityDone=false,answers={},attempts={},showHints={},activityState={},current=0;
function mission(n){if(n<1||n>8){location.hash='world';return}if((n===8&&!state.done.includes(7))||(n>1&&n<8&&!state.done.includes(n-1))){layout(`<div class="panel"><h1>One discovery at a time.</h1><p>Complete the previous mission to unlock this one.</p><a class="btn" href="#world">View mission map</a></div>`);return}current=n;activityDone=state.rewards.includes('activity'+n);answers={};attempts={};showHints={};activityState={};layout(`<div class="headrow"><div><a class="textlink" href="#world">← Mission map</a><div class="eyebrow" style="margin-top:23px">${n===8?'BOSS CHALLENGE':'MISSION 0'+n} · ${esc(state.level)}</div><h1 style="font-size:2.5rem;margin-top:10px">${n===8?'The athlete case':missions[n-1][0]}</h1></div><span class="chip">${n===8?50:20} investigation XP</span></div><div class="workgrid"><section class="activity"><div id="activity"></div><div id="activity-feedback" aria-live="polite"></div></section><section class="panel"><div class="eyebrow">CHECK YOUR UNDERSTANDING</div><h2 style="font-size:1.4rem;margin-top:12px">Make the connection.</h2><div id="quiz"></div><div id="finish"></div></section></div>`);renderActivity(n);renderQuiz(n);updateFinish()}
function renderQuiz(n){$('#quiz').innerHTML=checks[n].map((x,i)=>`<div class="quizquestion"><span class="quiztype">${['Recall','Apply','Reason'][i]} · ${i+1}/3</span><h3 style="margin-top:10px">${x.text}</h3>${x.options.map((o,j)=>`<button class="choice ${answers[i]===j?'selected':''}" data-q="${i}" data-a="${j}" ${answers[i]===x.answer?'disabled':''}>${o}</button>`).join('')}${answers[i]!==undefined?`<div class="feedback ${answers[i]===x.answer?'':'wrong'}">${answers[i]===x.answer?'Correct. ':'Look again. '}${x.why}</div>`:''}${(attempts[i]||0)>=2&&answers[i]!==x.answer?`<button class="btn secondary" data-hint="${i}">Show me</button>${showHints[i]?`<div class="hint">${x.options[x.answer]}<p>${x.why}</p></div>`:''}`:''}</div>`).join('');$$('[data-q]').forEach(b=>b.onclick=()=>{const i=+b.dataset.q,j=+b.dataset.a;answers[i]=j;if(j===checks[n][i].answer){reward('q'+n+'-'+i,10);state.weak=state.weak.filter(w=>w!==n+'-'+i)}else{attempts[i]=(attempts[i]||0)+1;if(!state.weak.includes(n+'-'+i))state.weak.push(n+'-'+i)}save();renderQuiz(n);updateFinish()});$$('[data-hint]').forEach(b=>b.onclick=()=>{showHints[b.dataset.hint]=true;renderQuiz(n)})}
function updateFinish(){let ready=activityDone&&checks[current].every((x,i)=>answers[i]===x.answer);$('#finish').innerHTML=`<p class="note">${activityDone?'✓ Investigation completed':'Complete the investigation'} · ${Object.keys(answers).filter(i=>answers[i]===checks[current][i].answer).length}/3 checks passed</p><button class="btn full" id="complete" ${ready?'':'disabled'}>${state.done.includes(current)?'Mission completed · Back to map':'Complete mission →'}</button>`;$('#complete').onclick=()=>{if(!state.done.includes(current)){state.done.push(current);if(current===8)reward('boss',50);save()}toast(current===8?'Framework Key (Skeletal System) earned · Skeletal Master!':'Mission complete · Next mission unlocked');location.hash='world'}}
function feedback(msg,ok=false,tone){const fbTone=(tone===null?'info':((tone===undefined?ok:tone)?'':'wrong'));$('#activity-feedback').innerHTML=`<div class="feedback ${fbTone}">${msg}</div>`;if(ok){activityDone=true;if(current!==8)reward('activity'+current,20);else{if(!state.rewards.includes('activity8'))state.rewards.push('activity8');save()}updateFinish()}}
function matchActivity(rows,options,id,callback){return `<div id="${id}">${rows.map((r,i)=>`<div class="matchrow"><label for="${id}-${i}" class="label">${r[0]}</label><select class="input" id="${id}-${i}" data-match="${i}"><option value="">Choose…</option>${options.map((x,j)=>`<option value="${j}">${x}</option>`).join('')}</select></div>`).join('')}</div><button class="btn spacer" id="check-match">Check my matches</button>`}
function wireMatch(rows,id,callback){$('#check-match').onclick=()=>{let correct=rows.every((r,i)=>+$('#'+id+'-'+i).value===r[1]&&$('#'+id+'-'+i).value!=='');callback(correct)}}
function renderActivity(n){let a=$('#activity');if(n===1){a.innerHTML=`<h2>Light up the skeleton</h2><p>A typical adult skeleton has 206 bones. Explore the central axis and the limbs with their girdles.</p><div class="controls" id="toggles">${['All bones','Axial','Appendicular'].map((x,i)=>`<button data-mode="${['all','axial','appendicular'][i]}" class="${i===0?'selected':''}">${x}</button>`).join('')}</div><div class="diagram" id="skeleton">${skeleton('all',true)}</div><p class="diagramlegend">Simplified learning diagram · Anterior view</p><div class="hint" id="light-prompt">1. Select Axial to highlight the skull, spine, ribs and sternum.</div>`;let step=0;$$('[data-mode]').forEach(b=>b.onclick=()=>{$('#skeleton').innerHTML=skeleton(b.dataset.mode,true);$$('[data-mode]').forEach(x=>x.classList.toggle('selected',x===b));if(step===0&&b.dataset.mode==='axial'){step=1;$('#light-prompt').textContent='2. Now select Appendicular: shoulder girdle, arms, pelvic girdle and legs.'}else if(step===1&&b.dataset.mode==='appendicular'){step=2;$('#light-prompt').textContent='✓ Both divisions identified. Which division includes the limbs? Answer in the checks.';feedback('You identified the axial and appendicular skeleton.',true)}})}
if(n===2){a.innerHTML=`<h2>A shape for every job</h2><p>Drag a bone into its category, or use the menus. Look at shape before choosing.</p><div class="grid twocol">${[['Femur','Long shaft; thigh'],['Carpals','Small, roughly cube-shaped; wrist'],['Sternum','Broad, flat plate; chest'],['Vertebra','Complex form; spine']].map(([x,t],i)=>`<div class="panel" draggable="true" data-drag="${i}"><div class="diagram" style="min-height:100px;margin:0">${boneShape(i)}</div><h3>${x}</h3><p class="micro">${t}</p></div>`).join('')}</div>${matchActivity([['Long bone → movement / weight bearing',0],['Short bone → small gliding movements',1],['Flat bone → protection',2],['Irregular bone → support / movement',3]],['Femur','Carpals','Sternum','Vertebra'],'bones')}<p class="note">This mission focuses on four groups. Sesamoid bones, such as the patella, are another group.</p><label class="label" for="reason">Why would every bone being shaped like a femur be a problem?</label><textarea id="reason" class="input" placeholder="Think about protection, flexibility and different jobs…"></textarea>`;$$('[data-drag]').forEach(b=>b.ondragstart=e=>e.dataTransfer.setData('text/plain',b.dataset.drag));$$('#bones .matchrow').forEach((row,i)=>{row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();$('#bones-'+i).value=e.dataTransfer.getData('text/plain')}});wireMatch([['',0],['',1],['',2],['',3]],'bones',ok=>{if($('#reason').value.trim().length<12){feedback('Add a short explanation about how different shapes support different jobs.',false,null);return}feedback(ok?'Correct matches. Compare your explanation: a broad sternum protects organs; small carpals allow flexibility; a long femur acts as a lever. Your writing is for reflection, not automatically graded.':'Try again: long shafts act as levers; small carpals glide; a broad sternum protects; vertebrae have complex shapes.',ok)})}
if(n===3){const parts=[['Compact bone','Dense outer bone gives strength.'],['Spongy bone','Internal trabecular lattice supports loads with less material.'],['Marrow cavity','Central cavity in the shaft; contains marrow.'],['Red marrow','Produces blood cells; in adults found mainly in the axial skeleton and selected proximal long-bone ends.'],['Yellow marrow','Fat-rich tissue in the adult shaft cavity.'],['Cartilage','Smooth covering reduces friction at a joint.'],['Periosteum','Outer membrane contains vessels and supports repair; absent over joint surfaces.']];a.innerHTML=`<h2>Strong outside. Clever inside.</h2><p>Tap each numbered structure to reveal its function.</p><div class="diagram"><svg viewBox="0 0 400 350" role="img" aria-label="Schematic long bone cutaway showing compact shell, internal lattice and yellow marrow cavity"><path d="M150 60Q105 5 78 50Q52 82 103 108l22 154q-52 38-17 62 28 18 54-16 30 29 51 4 24-33-18-52l-15-150q42-32 12-58-23-20-42 8Z" fill="#e2cba4" stroke="#a88f68" stroke-width="3"/><path d="m132 102 13 165 27-2-14-162Z" fill="#efca5c" stroke="#b08d35"/><path d="m105 55 45 40 35-37m-82 12 60 13m-57 201 59 20 28-20m-61-190 10 175" fill="none" stroke="#a45a59" stroke-width="6"/><path d="M77 50q19-29 40-8M108 324q27 12 49-17" fill="none" stroke="#77bfc1" stroke-width="9"/>${[[180,165],[171,77],[146,216],[112,76],[157,147],[83,43],[122,167]].map(([x,y],i)=>`<g><path d="M${x} ${y}H${250+i%2*40}" stroke="#789393"/><circle cx="${x}" cy="${y}" r="4" fill="#087e80"/><text x="${255+i%2*40}" y="${y+5}" fill="#123448" font-size="16">${i+1}</text></g>`).join('')}</svg></div><div class="controls">${parts.map(([x],i)=>`<button data-partinfo="${i}">${i+1}. ${x}</button>`).join('')}</div><div class="feedback" id="partinfo">Choose a structure.</div><h3>Predict: which model represents spongy bone?</h3><div class="grid twocol"><button class="choice" data-model="solid"><svg viewBox="0 0 100 70" height="65"><rect x="10" y="10" width="80" height="50" fill="#8dafaa"/></svg><br>Solid block</button><button class="choice" data-model="lattice"><svg viewBox="0 0 100 70" height="65"><path d="M10 10h80v50H10Z M10 10l80 50M90 10 10 60M50 10v50M10 35h80" stroke="#5d9b91" stroke-width="4" fill="none"/></svg><br>Supporting lattice</button></div>`;let seen=new Set();$$('[data-partinfo]').forEach(b=>b.onclick=()=>{seen.add(+b.dataset.partinfo);$('#partinfo').textContent=parts[b.dataset.partinfo].join(': ');b.classList.add('selected')});$$('[data-model]').forEach(b=>b.onclick=()=>feedback(b.dataset.model==='lattice'?(seen.size===7?'Yes. A lattice supports loads with less material. You explored all seven structures.':'Correct prediction. Explore all seven structure labels, then confirm the model.'):'A solid block does not explain the spaces between trabeculae. Try the lattice.',b.dataset.model==='lattice'&&seen.size===7,b.dataset.model==='lattice'))}
if(n===4){const joints=[['Shoulder','Ball-and-socket',3,'Moves in several planes and rotates.'],['Elbow','Hinge',1,'Mainly bends and straightens.'],['Between wrist carpals','Gliding',2,'Small sliding movements between carpal bones. The main wrist joint is condyloid.'],['Upper neck','Pivot',1,'Rotation around one main axis between atlas and axis.'],['Skull','Sutures',0,'Fibrous joints with little or no movement.']];a.innerHTML=`<h2>Move your body</h2><p>Select a joint. Observe its movement, then choose the matching movement description.</p><div class="controls">${joints.map((j,i)=>`<button data-joint="${i}">${j[0]}</button>`).join('')}</div><div id="joint-display"></div><div id="joint-task"></div><p class="note">Movement categories are simplified for comparison; they are not a medical scoring scale.</p><button class="btn line" id="three-d">Explore shoulder in 3D</button><div id="three-panel"></div>`;let seen=new Set();function setJoint(i){activityState.joint=i;let j=joints[i];$('#joint-display').innerHTML=`<div class="diagram"><svg viewBox="0 0 360 250" role="img" aria-label="Simplified ${j[1]} movement diagram"><path d="M65 150h115" stroke="#99bdb4" stroke-width="26" stroke-linecap="round"/><circle cx="180" cy="150" r="24" fill="#e4efe9" stroke="#40958c" stroke-width="5"/><g class="${['jointball','jointhinge','jointglide','jointpivot',''][i]}"><path d="M180 150h110" stroke="#74a99e" stroke-width="24" stroke-linecap="round"/></g><text x="35" y="40" font-size="22" fill="#163e4b">${j[1]}</text><text x="35" y="225" font-size="14" fill="#567680">${i===2?'Schematic only: small sliding motion':i===3?'Schematic only: one rotational axis':'Simplified movement model'}</text></svg></div><p>${j[3]}</p>`;$('#joint-task').innerHTML=`<label for="movement">How does this joint move?</label><select id="movement" class="input"><option value="">Choose…</option><option value="0">0 · Little or no movement</option><option value="1">1 · One main plane / axis</option><option value="2">2 · Small glides in different directions</option><option value="3">3 · Several planes plus rotation</option></select><button class="btn" id="joint-check">Check movement</button>`;$('#joint-check').onclick=()=>{let ok=$('#movement').value!==''&&+$('#movement').value===j[2];if(ok)seen.add(i);feedback(ok?(seen.size===5?'All five joint types explored. The shoulder allows several axes of movement.':`Correct. ${seen.size}/5 joints explored. Choose another joint.`):'Observe the movement and read the short description. Try again.',ok&&seen.size===5,ok)}}$$('[data-joint]').forEach(b=>b.onclick=()=>setJoint(+b.dataset.joint));setJoint(0);$('#three-d').onclick=async()=>{$('#three-panel').innerHTML='<p>Loading the isolated joint model…</p>';try{await import('./shoulder.js').then(m=>m.mount($('#three-panel')))}catch{$('#three-panel').innerHTML='<p>3D is unavailable here. The interactive 2D joint model above remains available.</p>'}}}
if(n===5){a.innerHTML=`<h2>Demolition vs construction</h2><p><b>Osteoclasts</b> remove bone. <b>Osteoblasts</b> form new bone.</p><div class="controls">${['A · Remove 3 / build 3','B · Remove 5 / build 2','C · Remove 2 / build 5'].map((x,i)=>`<button data-round="${i}">${x}</button>`).join('')}</div><div class="diagram"><div><div id="blocks" class="blocks"></div><p id="mass" style="text-align:center">Starting bone mass: 10 units</p></div></div><label for="prediction">Predict the final bone mass.</label><select class="input" id="prediction"><option value="">Choose…</option><option value="0">Stays the same</option><option value="1">Decreases</option><option value="2">Increases</option></select><button class="btn" id="run">Run remodeling</button><p class="note">Old bone → osteoclast resorption → osteoblast formation → new bone.</p><div id="life"></div>`;let round=0,done=new Set();const data=[[3,3],[5,2],[2,5]];function blocks(count,removed=0){$('#blocks').innerHTML=Array.from({length:count},()=>'<span class="block"></span>').join('')+Array.from({length:removed},()=>'<span class="block removed"></span>').join('')}blocks(10);$$('[data-round]').forEach(b=>b.onclick=()=>{round=+b.dataset.round;blocks(10);$('#mass').textContent='Starting bone mass: 10 units';$('#prediction').value='';$$('[data-round]').forEach(x=>x.classList.toggle('selected',x===b))});$('#run').onclick=()=>{let [remove,build]=data[round],ok=$('#prediction').value!==''&&+$('#prediction').value===round;blocks(10-remove+build,Math.max(0,remove-build));$('#mass').textContent=`10 − ${remove} + ${build} = ${10-remove+build} units`;if(ok)done.add(round);feedback(ok?`Correct prediction. ${done.size}/3 rounds completed. Formation minus removal determines the change.`:'Compare formation with removal. Equal means balance; greater removal means loss.',false,ok);if(done.size===3){$('#life').innerHTML=`<h3>Connect to real life</h3>${matchActivity([['Regular weight-bearing exercise',0],['Long-term inactivity',1],['Aging with formation below removal',1]],['Can support bone strength','Can favor bone loss'],'life')}`;wireMatch([['',0],['',1],['',1]],'life',ok=>feedback(ok?'You connected loading and remodeling. These are simplified tendencies, not predictions for an individual.':'Exercise provides mechanical loading; inactivity and an imbalance during aging can favor loss.',ok))}}}
if(n===6){const stages=['Blood clot / hematoma','Soft callus','Hard callus','Remodeling'],desc=['Damaged vessels form a clot.','Fibrocartilaginous tissue bridges the break.','New bone replaces much of the soft callus.','Bone is reshaped and strengthened.'];let order=[2,0,3,1];a.innerHTML=`<h2>Repair the bone</h2><p>Move the four stages into order. Drag them, or use the arrow buttons.</p><div id="sequence"></div><button class="btn" id="sequence-check">Test the sequence</button><div id="healing"></div><h3 class="spacer">Why use a cast?</h3><p>Which situation better supports repair?</p><div class="controls"><button data-cast="unstable">Repeated movement at the break</button><button data-cast="stable">Stabilized fracture</button></div>`;let sequenceOK=false,castOK=false;function draw(){ $('#sequence').innerHTML=order.map((s,i)=>`<div class="sequenceitem" draggable="true" data-index="${i}"><span>${i+1}. ${stages[s]}</span><span><button aria-label="Move ${stages[s]} up" data-up="${i}" ${i===0?'disabled':''}>↑</button><button aria-label="Move ${stages[s]} down" data-down="${i}" ${i===3?'disabled':''}>↓</button></span></div>`).join('');$$('[data-up]').forEach(b=>b.onclick=()=>move(+b.dataset.up,-1));$$('[data-down]').forEach(b=>b.onclick=()=>move(+b.dataset.down,1));$$('[data-index]').forEach(b=>{b.ondragstart=e=>e.dataTransfer.setData('text/plain',b.dataset.index);b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();let from=+e.dataTransfer.getData('text/plain'),to=+b.dataset.index;if(from>=0&&from<4){order.splice(to,0,order.splice(from,1)[0]);draw()}}})}function move(i,d){[order[i],order[i+d]]=[order[i+d],order[i]];draw()}draw();$('#sequence-check').onclick=()=>{sequenceOK=order.every((x,i)=>x===i);feedback(sequenceOK?'Correct sequence. Select each stage to see the repair progress.':'Start with the clot, then the soft bridge, then a hard bony callus, then reshaping.',sequenceOK&&castOK,sequenceOK);if(sequenceOK){$('#healing').innerHTML=`<div class="controls">${stages.map((s,i)=>`<button data-stage="${i}">${i+1}. ${s}</button>`).join('')}</div><div class="diagram" id="stage-visual"></div>`;$$('[data-stage]').forEach(b=>b.onclick=()=>{const i=+b.dataset.stage;$('#stage-visual').innerHTML=`<svg viewBox="0 0 320 160" role="img" aria-label="${stages[i]} simplified fracture repair"><path d="M30 65h112l-10 17 18 12H30M290 65H164l12 17-18 12h132" fill="#abc4b3" stroke="#648e7d" stroke-width="3"/><ellipse cx="153" cy="80" rx="${[22,34,30,15][i]}" ry="${[26,29,25,16][i]}" fill="${['#a94f5c','#dbb9b1','#acc5ab','#c5d6bd'][i]}" opacity=".85"/></svg><p>${desc[i]}</p>`});$('[data-stage]').click()}};$$('[data-cast]').forEach(b=>b.onclick=()=>{castOK=b.dataset.cast==='stable';feedback(castOK?'Stability limits movement that could disrupt repair tissue.':'Repeated movement can disrupt the developing bridge.',sequenceOK&&castOK)})}
if(n===7){clinical(a,()=>feedback('All four evidence-based cases solved. Complete the three checks to finish the mission.',true))}
if(n===8){a.innerHTML=`<div class="eyebrow">THE ATHLETE CASE</div><h2 style="margin-top:14px">One landing. Five clues.</h2><p>A student lands badly during basketball. The ankle is swollen and painful, movement is difficult, and no fracture is visible on the X-ray.</p><div class="panel" style="background:#edf5f4;margin:22px 0"><b>Your investigation</b><p>Which structure is involved? Ligament or tendon? What injury and function do the clues suggest? Why would stability help?</p></div><label for="boss-reason">Explain why limiting movement could support recovery.</label><textarea class="input" id="boss-reason" placeholder="Link stability to the damaged tissue…"></textarea><button class="btn" id="boss-explain">Compare my reasoning</button><div id="boss-model"></div><p class="note">For learning purposes only. This is not medical diagnosis. A real injury needs appropriate professional assessment.</p>`;$('#boss-explain').onclick=()=>{if($('#boss-reason').value.trim().length<15){feedback('Write a sentence linking stability, the injured ligament and repair.',false,null);return}$('#boss-model').innerHTML='<div class="feedback">Model reasoning: reducing disruptive movement protects injured ligament tissue while it repairs. Compare this with your explanation.</div><label><input type="checkbox" id="reflect"> My explanation links stability to tissue repair, or I have revised it.</label>';$('#reflect').onchange=e=>{if(e.target.checked)feedback('Reasoning reflected on. Use the three checks to confirm the structure, injury and affected function.',true)}}}}
function boneShape(i){return `<svg viewBox="0 0 180 100" style="height:100px" role="img" aria-label="Simplified ${['femur','carpals','sternum','vertebra'][i]} shape"><g fill="#b6cbb9" stroke="#6c9382" stroke-width="2">${['<path d="M36 22q-15-18-23-3-8 18 15 20l95 43q4 22 20 10 10-8-2-15 22-5 9-21-12-11-23 3L38 30Z"/>','<rect x="42" y="18" width="26" height="25" rx="7"/><rect x="74" y="15" width="26" height="25" rx="7"/><rect x="107" y="21" width="26" height="25" rx="7"/><rect x="36" y="50" width="24" height="27" rx="7"/><rect x="66" y="48" width="24" height="27" rx="7"/><rect x="96" y="48" width="24" height="27" rx="7"/><rect x="126" y="50" width="23" height="27" rx="7"/>','<path d="M74 8h32l10 16-16 14 2 37-11 19-10-19 2-37-18-14Z"/>','<path d="M70 28 45 8l-7 13 24 24-40 5v13l44 1 13 18 6 14 11-1 6-17 16-15 41-1V48l-37-3 19-26-10-8-25 21Z"/><ellipse cx="91" cy="49" rx="19" ry="14" fill="#f0f7f6"/>'][i]}</g></svg>`}
const cases=[{name:'Case A · The aching knee',story:'A 65-year-old adult has knee pain. Joint cartilage has gradually worn down.',structure:'Articular cartilage',condition:'Osteoarthritis',evidence:'Gradual cartilage wear',why:'The cartilage-wear clue supports osteoarthritis in this learning case.'},{name:'Case B · The immune clue',story:'Several joints are swollen. Evidence shows the immune system attacking joint tissue.',structure:'Joint lining',condition:'Rheumatoid arthritis',evidence:'Immune attack on joint tissue',why:'An autoimmune attack on joint tissue supports rheumatoid arthritis.'},{name:'Case C · The volleyball shoulder',story:'A volleyball student has shoulder pain after repeated movement. A fluid-filled cushioning sac is swollen.',structure:'Bursa',condition:'Bursitis',evidence:'Inflamed cushioning sac',why:'The inflamed fluid-filled bursa is the key clue for bursitis.'},{name:'Case D · The twisted ankle',story:'A basketball student lands badly and twists an ankle. A ligament is overstretched.',structure:'Ligament',condition:'Sprain',evidence:'Overstretched ligament',why:'An overstretched or torn ligament is a sprain; a tendon injury would be a different structure.'}];
function clinical(el,onDone){let selected=0,solved=new Set();function render(){let c=cases[selected];el.innerHTML=`<div class="eyebrow">BODY DETECTIVE · CASE FILES</div><h2 style="margin-top:12px">Follow the evidence.</h2><div class="controls">${cases.map((x,i)=>`<button data-case="${i}" class="${i===selected?'selected':''}">Case ${'ABCD'[i]} ${solved.has(i)?'✓':''}</button>`).join('')}</div><div class="panel" style="background:#eff6f5"><h3>${c.name}</h3><p>${c.story}</p></div>${[['System',['Skeletal System','Respiratory System','Excretory System']],['Structure',cases.map(x=>x.structure)],['Condition',cases.map(x=>x.condition)],['Evidence',cases.map(x=>x.evidence)]].map(([label,opts],i)=>`<label class="label" for="clinical-${i}">${label}</label><select class="input" id="clinical-${i}"><option value="">Choose…</option>${opts.map(x=>`<option>${x}</option>`).join('')}</select>`).join('')}<button class="btn full" id="diagnose">Submit diagnosis</button><div id="case-feedback" aria-live="polite"></div><p class="note">For learning purposes only. This is not medical diagnosis.</p>`;$$('[data-case]').forEach(b=>b.onclick=()=>{selected=+b.dataset.case;render()});$('#diagnose').onclick=()=>{let correct=['Skeletal System',c.structure,c.condition,c.evidence].every((x,i)=>$('#clinical-'+i).value===x);$('#case-feedback').innerHTML=`<div class="feedback ${correct?'':'wrong'}">${correct?'Good diagnosis. Your evidence supports '+c.condition+'. '+c.why:'Look again at the structure affected. '+(selected===0?'Focus on cartilage wear.':selected===1?'Focus on immune attack.':selected===2?'Which structure is a cushioning sac?':'Which tissue connects bone to bone?')}</div>`;if(correct){solved.add(selected);reward('case'+selected,30);if(solved.size===4)onDone();else $('#case-feedback').innerHTML+=`<p class="note">${solved.size}/4 solved. Open the next case above.</p>`}}}render()}
function detective(){layout(`<div class="headrow"><div><div class="eyebrow">MEDICAL MYSTERIES</div><h1 style="margin-top:12px">Body detective</h1><p>A good explanation starts with good evidence.</p></div><span class="chip">4 case files · 120 XP</span></div><div class="workgrid"><section class="activity" id="clinical"></section><aside class="panel" style="align-self:start"><h3>Your investigation toolkit</h3><ol class="learnlist"><li>Read the story.</li><li>Locate the affected structure.</li><li>Connect the evidence to a condition.</li><li>Check your explanation.</li></ol><p>These simplified fictional cases are for learning anatomy, not diagnosing yourself or someone else.</p><a class="btn secondary" href="#world">Explore the Skeletal System world</a></aside></div>`,'detective');clinical($('#clinical'),()=>toast('Medical Investigator · All four cases solved'))}
function connections(){layout(`<div class="headrow"><div><div class="eyebrow">SYSTEM CONNECTION · PREVIEW MISSION</div><h1 style="margin-top:12px">Running on a hot day</h1><p>One kilometre. Six systems working together.</p></div><span class="chip">+35 XP</span></div><div class="workgrid"><section class="activity"><h2>Your body responds.</h2><div class="grid twocol">${[['Breathing increases','More oxygen enters.'],['Heart rate rises','Blood delivers oxygen.'],['Muscles contract','Bones act as levers.'],['Sweating increases','Cooling costs water.']].map(([x,y])=>`<div class="panel"><h3>${x}</h3><p class="micro">${y}</p></div>`).join('')}</div><h3 class="spacer">Match each system to its contribution.</h3>${matchActivity([['Respiratory System',0],['Circulatory System',1],['Muscular System',2],['Skeletal System',3],['Integumentary System',4],['Excretory System',5]],['Oxygen intake','Oxygen transport','Movement through contraction','Support and leverage','Cooling through sweating','Water conservation and balance'],'systems')}<div id="connect-feedback" aria-live="polite"></div></section><section class="panel" style="align-self:start"><div class="eyebrow">EXPLAIN THE CONNECTION</div><h2 style="margin-top:14px;font-size:1.5rem">Tell the whole story.</h2><p>Explain how at least three systems work together during the run.</p><textarea class="input" id="connection-reason" placeholder="The Respiratory System… The Circulatory System… This helps the muscles…"></textarea><button class="btn full" id="compare">Compare with a model</button><div id="connection-model"></div></section></div>`,'connect');let matched=false;wireMatch([['',0],['',1],['',2],['',3],['',4],['',5]],'systems',ok=>{matched=ok;$('#connect-feedback').innerHTML=`<div class="feedback ${ok?'':'wrong'}">${ok?'All six systems matched. Now explain how at least three connect.':'Check the pathway: lungs take in oxygen, blood transports it, muscles pull on bones. Skin cools; kidneys help regulate water.'}</div>`});$('#compare').onclick=()=>{if($('#connection-reason').value.trim().length<35){$('#connection-model').innerHTML='<div class="feedback wrong">Write a few connected sentences about at least three systems.</div>';return}$('#connection-model').innerHTML='<div class="feedback">Model: the Respiratory System takes in oxygen; the Circulatory System carries it to muscles. The Muscular System pulls on bones of the Skeletal System for movement. Sweating through the Integumentary System cools the body, while the kidneys of the Excretory System help conserve water.</div><p class="note">Your writing is a reflection, not automatically graded.</p><label><input id="connect-reflect" type="checkbox"> I linked at least three systems and compared my explanation.</label>';$('#connect-reflect').onchange=e=>{if(e.target.checked&&matched){reward('connection',35);toast('System Thinker badge earned')}else if(e.target.checked)toast('Complete the six matches first, then confirm your reflection.')}}}
function badges(){const items=[['ANATOMY EXPLORER',state.done.includes(1),'Complete Meet your skeleton.'],['FUNCTION DETECTIVE',state.done.includes(3),'Complete Inside a bone.'],['MEDICAL INVESTIGATOR',[0,1,2,3].every(i=>state.rewards.includes('case'+i)),'Solve all four patient cases.'],['SYSTEM THINKER',state.rewards.includes('connection'),'Connect six systems during a run.'],['SKELETAL MASTER · Skeletal System',state.done.includes(8),'Complete The athlete case.']];layout(`<div class="headrow"><div><div class="eyebrow">YOUR DISCOVERIES, RECOGNIZED</div><h1 style="margin-top:12px">My achievements</h1><p>Every badge represents something you understand.</p></div><span class="chip">${items.filter(x=>x[1]).length}/5 earned</span></div><div class="grid three">${items.map(([name,earned,desc])=>`<div class="badge ${earned?'':'locked'}"><span>✵</span><h3>${name}</h3><p>${desc}</p><b class="micro">${earned?'EARNED':'LOCKED'}</b></div>`).join('')}</div><div class="finalmission"><div><h3>Framework Key (Skeletal System)</h3><p>${state.done.includes(8)?'You earned the first System Key.':'Complete the Skeletal System boss challenge to earn your first key.'}</p></div><span style="font-size:2rem">⚿</span></div>`,'badge')}
function dashboard(){layout(`<div class="headrow"><div><div class="eyebrow">YOUR PERSONAL EXPEDITION</div><h1 style="margin-top:12px">Welcome, ${esc(state.name)}.</h1><p>Your next discovery is waiting.</p></div><a href="#mission/${nextMission()}" class="btn">Continue mission →</a></div>${!storageOK?'<div class="feedback wrong">Browser storage is unavailable. Progress lasts for this session only.</div>':''}<div class="grid three"><section class="panel dark"><h3>Your experience</h3><h1>${state.xp} <small>XP</small></h1><p>Level ${Math.floor(state.xp/150)+1} · ${esc(state.level)}</p></section><section class="panel"><h3>Skeletal System progress</h3><h1>${pct()}%</h1><p>${status(pct())} · ${state.done.filter(x=>x<8).length}/7 missions</p><div class="bar"><i style="width:${pct()}%"></i></div></section><section class="panel"><h3>System keys</h3><h1>${keysEarned()}<small> / 6</small></h1><p>${keysEarned()?'System Keys earned in this browser.':'Finish a final challenge to earn your first key.'}</p></section></div><div class="grid twocol spacer"><section class="panel"><h3>Concepts to revisit</h3>${state.weak.length?state.weak.map(w=>{let [n,i]=w.split('-').map(Number);return `<p><a class="textlink" href="#mission/${n}">${checks[n][i].text}</a></p>`}).join(''):'<p>No concepts flagged yet. Your checks will help identify what to revisit.</p>'}</section><section class="panel"><div class="eyebrow">DAILY CHALLENGE</div><h3 style="margin-top:14px">Protect or move?</h3><p>Why are the ribs better suited to protecting chest organs than finger bones?</p><a class="textlink" href="#daily">Take the challenge →</a></section></div><section class="panel"><h3>Make it yours</h3><label for="nickname">First name or nickname only</label><input class="input" id="nickname" maxlength="24" value="${esc(state.name)}"><label for="dash-level">Challenge level</label><select class="input" id="dash-level">${['Explorer','Challenger','Master'].map(x=>`<option ${x===state.level?'selected':''}>${x}</option>`).join('')}</select><label><input type="checkbox" id="motion" ${state.motion?'checked':''}> Reduce motion</label><div class="controls"><button class="btn" id="save-profile">Save preferences</button><button class="btn line" id="reset">Reset progress</button></div><div id="reset-confirm"></div><p class="note">Saved on this browser only. No account, email address or health information required.</p></section>`,'dashboard');$('#save-profile').onclick=()=>{state.name=$('#nickname').value.trim()||'Explorer';state.level=$('#dash-level').value;state.motion=$('#motion').checked;save();dashboard();toast('Preferences saved')};$('#reset').onclick=()=>{$('#reset-confirm').innerHTML='<div class="feedback wrong">This removes your points, completed missions and badges from this browser. <button class="btn line" id="confirm-reset">Yes, reset my progress</button></div>';$('#confirm-reset').onclick=()=>{state={...state,xp:0,done:[],rewards:[],weak:[]};save();dashboard();toast('Progress reset')}}}
function daily(){layout(`<div class="activity" style="max-width:760px;margin:auto"><div class="eyebrow">DAILY DISCOVERY</div><h1 style="margin-top:12px;font-size:2.4rem">Protect or move?</h1><p>Why do ribs work well as protection for chest organs?</p><div id="daily-options">${['Their curved arrangement forms a protective cage.','They are completely immovable.','They are longer than every other bone.'].map((t,i)=>`<button class="choice" data-daily="${i}">${t}</button>`).join('')}</div><div id="daily-feedback"></div><a class="textlink" href="#dashboard">← Back to dashboard</a></div>`,'dashboard');$$('[data-daily]').forEach(b=>b.onclick=()=>{$('#daily-feedback').innerHTML=`<div class="feedback ${+b.dataset.daily===0?'':'wrong'}">${+b.dataset.daily===0?'Correct. The rib cage surrounds vital chest organs while allowing breathing movements.':'Think about the curved cage surrounding the heart and lungs. The ribs can move during breathing.'}</div>`;if(+b.dataset.daily===0)reward('daily-'+new Date().toISOString().slice(0,10),10)})}
const refs=[['OpenStax · Divisions of the Skeletal System','https://openstax.org/books/anatomy-and-physiology-2e/pages/7-1-divisions-of-the-skeletal-system','Adult bone count, axial and appendicular skeleton.'],['OpenStax · Bone classification','https://openstax.org/books/anatomy-and-physiology-2e/pages/6-2-bone-classification','Long, short, flat and irregular bones.'],['OpenStax · Bone structure','https://openstax.org/books/anatomy-and-physiology-2e/pages/6-3-bone-structure','Compact and spongy bone, marrow, periosteum and bone cells.'],['OpenStax · Fractures and bone repair','https://openstax.org/books/anatomy-and-physiology-2e/pages/6-5-fractures-bone-repair','Hematoma, callus formation and remodeling.'],['OpenStax · Synovial joints','https://openstax.org/books/anatomy-and-physiology-2e/pages/9-4-synovial-joints','Movement and classification of synovial joints.'],['MedlinePlus · Joint disorders','https://medlineplus.gov/jointdisorders.html','Arthritis and bursitis overview.'],['MedlinePlus · Sprains and strains','https://medlineplus.gov/sprainsandstrains.html','Ligament and tendon injury distinctions.']];
function info(route){let content={sources:`<h1>Science references</h1><p>Learning explanations were checked against the following sources. Illustrations are original simplified teaching diagrams, not diagnostic images.</p><ul class="sourcelist">${refs.map(([t,u,d])=>`<li><a href="${u}" target="_blank" rel="noopener">${t} ↗</a><br>${d}</li>`).join('')}</ul>`,about:'<h1>Explore What’s Inside.<br>Discover What Keeps You Alive.</h1><p>InnerU means “Inside You”: an interactive, gamified journey through the human body and its major systems. Designed for Grade 10 General Science at Um Al-Emarat School.</p><p>Start with the Skeletal System world: seven investigations, three checks after each mission, four fictional patient cases, and a final athlete challenge. The other five worlds are coming next.</p><p>Explorer gives extra guidance, Challenger focuses on application, and Master emphasizes independent explanation. All learners work toward the same core science goals.</p><a class="btn" href="#world">Enter the Framework (Skeletal System)</a>',privacy:'<h1>Your learning stays with you.</h1><p>This MVP stores your optional nickname, preferences, points, answers needing review and mission completion in this browser’s local storage. Written explanations and case selections are not saved.</p><p>There is no application account or public leaderboard. Do not enter health information, medical records, diagnoses, contact details or student photos.</p><p>Clear local data using Reset Progress in your dashboard. Clearing browser storage also removes progress. Progress does not sync between devices.</p><p>The hosting service may use its own access controls and operational logs. External source links have their own privacy policies. Fonts are loaded from Google Fonts with local system fallbacks.</p><a class="btn secondary" href="#dashboard">Manage my progress</a>',attribution:'<h1>Attribution</h1><p>Teaching diagrams and interface code were created for InnerU. The running and science-investigator scenes are original AI-generated editorial illustrations; the interactive diagrams carry the scientific labels. Diagrams simplify anatomical forms and are not to scale.</p><p><a class="textlink" href="https://github.com/ashemag/human-atlas" target="_blank" rel="noopener">Human Atlas ↗</a> inspired the lightweight identify, highlight and isolate interaction concept. The interactive heart, skeletal and muscular atlases use adapted BodyParts3D 4.3 geometry by DBCLS under CC BY-SA 2.1 Japan.</p><p>Scientific references are linked on the Sources page. No textbook figures are reproduced.</p><p>DM Sans and Manrope typefaces are distributed under the SIL Open Font License via Google Fonts.</p>'};layout(`<section class="panel" style="max-width:900px">${content[route]}</section>`)}
function route(){const hash=location.hash.slice(1)||'home';if(hash==='circulatory')circWorld();else if(hash.startsWith('circulatory/')){const part=hash.split('/')[1];if(part==='mastery')circMastery();else if(part==='boss')circBoss();else circMission(+part)}else if(hash.startsWith('mission/'))mission(+hash.split('/')[1]);else ({home,world,dashboard,detective,connect:connections,badges,daily}[hash]||(()=>info(['sources','about','privacy','attribution'].includes(hash)?hash:'about')))();if(state.level==='Explorer'&&hash.startsWith('mission/')&&$('#activity'))$('#activity').insertAdjacentHTML('afterbegin','<p class="hint">Explorer tip: look at the diagram, read the short clue, then try. You can repeat every activity.</p>');if(state.level==='Master'&&hash.startsWith('mission/')&&$('#activity'))$('#activity').insertAdjacentHTML('afterbegin','<p class="hint">Master challenge: explain your prediction before checking. Connect the structure to its function.</p>');window.scrollTo(0,0)}
window.addEventListener('hashchange',route);

function animateXP(from,to){const el=$('.xp');if(!el)return;if(motionReduced()){el.textContent='✧ '+to+' XP';return}const start=performance.now();function tick(now){if(!el.isConnected)return;const t=Math.min(1,(now-start)/360);el.textContent='✧ '+Math.round(from+(to-from)*t)+' XP';if(t<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)}
